/bin/bash -lc "python -B check.py
python -B - <<'PY'
from service import offset

for page in (1, 2, 4, 100, 10**12):
    for size in range(1, 101):
        assert offset(page, size) == (page - 1) * size

for invalid in (-100, -1, 0, 1.0, 1.5, '1', None, True, False, [], {}):
    try:
        offset(invalid, 10)
    except ValueError:
        pass
    else:
        raise AssertionError(('page', invalid))

for invalid in (-100, -1, 0, 101, 1000, 1.0, 1.5, '1', None, True, False, [], {}):
    try:
        offset(1, invalid)
    except ValueError:
        pass
    else:
        raise AssertionError(('size', invalid))

print('Supplied check and pagination boundary/type checks passed.')
PY"

